def _html(language: str) -> str:
    blocks = []
    for number, (title_en, title_bn, body_en, body_bn) in enumerate(SECTIONS, 1):
        title, body = (title_bn, body_bn) if language == "bn" else (title_en, body_en)
        blocks.append(f"<h2>{number}. {escape(title)}</h2><p>{escape(body)}</p>")
    return "".join(blocks)


def terms_text() -> dict[str, str]:
    return {
        "title_en": "TURFBARI Terms & Conditions",
        "title_bn": "TURFBARI-এর শর্তাবলি",
        "body_en": _html("en"),
        "body_bn": _html("bn"),
    }
